urlset:
{{ base_url }}/
{% for std in standards %}
{{ base_url }}/{{ std.id }}
{# Served publications only. A sitemap tells a crawler a URL is worth indexing, and a
   withdrawn release or revision answers 410 - a crawl error on every pass, for as long as
   the history stays in the manifest, which is for ever. They remain listed for a reader on
   the standard's landing page, which is where "this existed and is gone" belongs. #}
{% for ml in std.sorted_major_lines() %}
{{ base_url }}/{{ std.id }}/v{{ ml.major }}
{% for rules in std.sorted_rules(ml.major) if rules.is_served %}
{{ base_url }}/{{ std.id }}/{{ rules.slug }}
{% endfor %}
{% endfor %}
{% for rel in std.sorted_releases() if rel.is_served %}
{{ base_url }}/{{ std.id }}/{{ rel.slug }}
{% endfor %}
{% endfor %}
